commands.commandLine:
$patterns = @('def parse_args','def parse_sort','class Entry','def render_path_list','def permissions_windows','def render_details','def tree_walk','def main')
foreach ($path in @('eza_port.py','executable','compile.sh','.tura\script\diff_verify.py')) {
  Write-Output $path
  $i=0
  Get-Content $path | ForEach-Object { $i++; foreach ($p in $patterns) { if ($_ -like "*$p*") { Write-Output ("{0}: {1}" -f $i, $_.Trim()) } }; if ($path -eq 'compile.sh' -and $_.Trim()) { Write-Output ("{0}: {1}" -f $i, $_.Trim()) }; if ($path -eq 'executable' -and $_ -like '*main*') { Write-Output ("{0}: {1}" -f $i, $_.Trim()) }; if ($path -like '*.py' -and ($_ -like '*def valid_samples*' -or $_ -like '*def invalid_samples*')) { Write-Output ("{0}: {1}" -f $i, $_.Trim()) } }
}
